const QON=QUIZ.every(x=>x.a);
const ORDER=(QON?['s1','sq']:['s1']).concat(['s2','sr','s3','s4','s5']);
let cur='s1';
function nx(){go(ORDER[ORDER.indexOf(cur)+1])}

function go(n){cur=n;document.querySelectorAll('.screen').forEach(s=>s.classList.remove('on'));$(n).classList.add('on');document.querySelectorAll('#prog i').forEach((d,i)=>d.classList.toggle('on',i===ORDER.indexOf(n)));if(n==='sq'){qi=0;showQ()}if(n==='s4')typeLetter();if(n==='s2'||n==='s5')burst()}

let pin="";
[1,2,3,4,5,6,7,8,9,'⌫',0,'🩷'].forEach(k=>{const b=document.createElement('button');b.textContent=k;b.onclick=()=>press(k);$('pad').appendChild(b)});
function press(k){
  if(k==='🩷')return;
  if(navigator.vibrate)navigator.vibrate(8);
  if(k==='⌫')pin=pin.slice(0,-1);else if(pin.length<4)pin+=k;
  document.querySelectorAll('#dots i').forEach((d,i)=>d.classList.toggle('f',i<pin.length));
  $('hint').textContent="";
  if(pin.length===4){
    if(pin===CODE)setTimeout(nx,300);
    else{$('dots').classList.add('shake');$('hint').textContent="Idhu illa, innoru thadava try pannu 🧿";
      setTimeout(()=>{$('dots').classList.remove('shake');pin="";document.querySelectorAll('#dots i').forEach(d=>d.classList.remove('f'))},450)}
  }
}

function openM(id,el){$(id).classList.add('on');if(el)el.classList.add('done');if(id==='m1')showSlide()}
function closeM(id){$(id).classList.remove('on');$('vid').pause()}
let si=0;
function showSlide(){const im=$('simg');im.onload=initScratch;im.src=SLIDES[si].src;$('scap').textContent=SLIDES[si].cap;$('scount').textContent=(si+1)+' / '+SLIDES.length;if(im.complete&&im.naturalWidth)initScratch()}
function step(d){si=(si+d+SLIDES.length)%SLIDES.length;showSlide()}

WHY.forEach(t=>{const c=document.createElement('button');c.className='card';c.innerHTML='<div><span class="f">🩷</span><span class="b">'+t+'</span></div>';c.onclick=()=>c.classList.toggle('flip');$('cards').appendChild(c)});

let typed=false,tmr;
function done(){clearInterval(tmr);$('lt').textContent=LETTER;$('sig').style.opacity=1;$('end').style.opacity=1;$('end').style.pointerEvents='auto'}
function typeLetter(){
  if(typed)return;typed=true;let i=0;
  $('lt').onclick=done;
  tmr=setInterval(()=>{$('lt').textContent=LETTER.slice(0,++i);if(i>=LETTER.length)done()},38);
}
function replay(){typed=false;clearInterval(tmr);$('lt').textContent='';$('sig').style.opacity=0;$('end').style.opacity=0;$('end').style.pointerEvents='none';pin='';document.querySelectorAll('#dots i').forEach(d=>d.classList.remove('f'));document.querySelectorAll('.box').forEach(b=>b.classList.remove('done'));qi=0;go('s1')}
let tx=0;
$('m1').addEventListener('touchstart',e=>{tx=e.target.id==='scr'?null:e.touches[0].clientX});
$('m1').addEventListener('touchend',e=>{if(tx===null)return;const d=e.changedTouches[0].clientX-tx;if(Math.abs(d)>50)step(d<0?1:-1)});
const fl=document.createElement('div');fl.className='fl';
const FE=['🩷','✨','🌸','🌷','🤍','💗','🌹','🌼'];for(let i=0;i<28;i++){const e=document.createElement('i');e.textContent=FE[i%FE.length];e.style.cssText='left:'+(Math.random()*100)+'%;font-size:'+(10+Math.random()*12)+'px;animation-duration:'+(14+Math.random()*14)+'s;animation-delay:-'+(Math.random()*20)+'s';fl.appendChild(e)}
for(let i=0;i<20;i++){const s=document.createElement('b');s.className='tw';s.textContent='✦';s.style.cssText='left:'+(Math.random()*100)+'%;top:'+(Math.random()*100)+'%;font-size:'+(8+Math.random()*10)+'px;animation-delay:-'+(Math.random()*3)+'s;animation-duration:'+(2.5+Math.random()*3)+'s';fl.appendChild(s)}
document.body.prepend(fl);

ORDER.forEach(()=>$('prog').appendChild(document.createElement('i')));
$('prog').firstChild.classList.add('on');

/* scratch cards */
const sc=$('scr');let sd=false;
function initScratch(){
  const im=$('simg'),w=im.clientWidth,h=im.clientHeight;if(!w)return;
  sc.width=w;sc.height=h;sc.style.opacity=1;sc.style.pointerEvents='auto';
  const x=sc.getContext('2d');x.globalCompositeOperation='source-over';
  const g=x.createLinearGradient(0,0,w,h);g.addColorStop(0,'#c98a99');g.addColorStop(1,'#8a2a42');
  x.fillStyle=g;x.fillRect(0,0,w,h);
  x.fillStyle='#ffe8ea';x.font='700 18px system-ui,sans-serif';x.textAlign='center';x.fillText('Scratch here 🩷',w/2,h/2);
  x.globalCompositeOperation='destination-out';
}
function sp(e){const r=sc.getBoundingClientRect(),x=sc.getContext('2d');x.beginPath();x.arc(e.clientX-r.left,e.clientY-r.top,24,0,7);x.fill()}
function chk(){const d=sc.getContext('2d').getImageData(0,0,sc.width,sc.height).data;let n=0,t=0;for(let i=3;i<d.length;i+=160){t++;if(d[i]<20)n++}if(n/t>.5){sc.style.opacity=0;sc.style.pointerEvents='none'}}
sc.addEventListener('pointerdown',e=>{sd=true;sc.setPointerCapture(e.pointerId);sp(e)});
sc.addEventListener('pointermove',e=>{if(sd)sp(e)});
sc.addEventListener('pointerup',()=>{sd=false;chk()});
sc.addEventListener('pointercancel',()=>{sd=false});

/* rating */
const WA='917538841390';
const TRAITS=['Mature','Anger','Shy','Care','Love','Beauty','Miss you'];
const rt=new Set();
function updRate(){
  const left=TRAITS.length-rt.size,ok=!left;
  $('rleft').textContent=ok?'Ellam mudinjidhu 🩷':left+' innum baaki';
  $('rsend').classList.toggle('off',!ok);
  const m='My scores for you 🩷\n'+TRAITS.map((n,i)=>n+': '+$('rs'+i).value+'/10').join('\n');
  $('rsend').href=ok?'https://wa.me/'+WA+'?text='+encodeURIComponent(m):'#';
}
TRAITS.forEach((n,i)=>{
  const l=document.createElement('label');l.innerHTML='<span>'+n+'</span><b id="rv'+i+'">–</b>';
  const r=document.createElement('input');r.type='range';r.min=0;r.max=10;r.value=5;r.id='rs'+i;
  const mark=()=>{rt.add(i);$('rv'+i).textContent=r.value;updRate()};
  r.oninput=mark;r.onpointerdown=mark;
  $('rate').append(l,r);
});
updRate();
$('rsend').addEventListener('click',()=>{if(rt.size===TRAITS.length)setTimeout(nx,1200)});

/* hearts burst */
function burst(){
  if(matchMedia('(prefers-reduced-motion:reduce)').matches)return;
  for(let i=0;i<22;i++){
    const e=document.createElement('i');e.className='bst';e.textContent=['🩷','✨','🌸','🌷','🤍','🎀'][i%6];
    const a=Math.random()*6.28,d=90+Math.random()*130;
    e.style.setProperty('--x',Math.cos(a)*d+'px');e.style.setProperty('--y',Math.sin(a)*d+'px');e.style.setProperty('--r',(Math.random()*160-80)+'deg');
    document.body.appendChild(e);setTimeout(()=>e.remove(),1700);
  }
}

/* date quiz (shows only when QUIZ answers are filled in) */
let qi=0,qw=0;
function showQ(){qw=0;$('qq').textContent=QUIZ[qi].q;$('qd').value='';$('qm').textContent='';$('qskip').style.display='none';$('qc').textContent=(qi+1)+' / '+QUIZ.length}
function chkQ(){
  const x=QUIZ[qi],v=$('qd').value;if(!v)return;
  const ok=x.md?v.slice(5)===x.a.slice(5):v===x.a;
  if(ok){$('qm').textContent='Correct 🩷';setTimeout(nextQ,700)}
  else{qw++;$('qm').textContent=qw<2?'Illa da 😂 innoru thadava':'Nalla yosichi sollu 🤨';if(qw>=2)$('qskip').style.display='inline-block'}
}
function skipQ(){const a=QUIZ[qi].a.split('-');$('qm').textContent='Answer: '+a[2]+'/'+a[1]+(QUIZ[qi].md?'':'/'+a[0])+' 🩷';setTimeout(nextQ,1800)}
function nextQ(){if(qi<QUIZ.length-1){qi++;showQ()}else nx()}
